"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[460],{460(e,n,i){i.d(n,{content:()=>d,description:()=>a,keywords:()=>h,title:()=>t});i(5043);var r=i(7295),s=i(579);const t="Bett 2026: WhimsyLabs l\xe4dt Sie nach London ein",a="WhimsyLabs kehrt zur Bett UK 2026 in die Startup Zone zur\xfcck, um unsere preisgekr\xf6nte virtuelle Laborplattform zu pr\xe4sentieren. Besuchen Sie uns am Stand FS10.",h=["Bett 2026","Bett UK Ausstellung","EdTech Messe London","virtuelles Labor Demo","Bildungstechnologie Startup","WhimsyLabs Bett","ExCel London EdTech","MINT-Bildung Innovation","virtuelle Laborplattform","Naturwissenschaft Bildungstechnologie"],d=(0,s.jsxs)("div",{children:[(0,s.jsx)("p",{children:"Ich freue mich sehr, ank\xfcndigen zu k\xf6nnen, dass WhimsyLabs im Januar 2026 wieder zur Bett UK zur\xfcckkehrt! Nach unserer fantastischen Erfahrung auf der Bett 2025, wo wir eine Auszeichnung vom Kids Judge Bett Award erhielten, kehren wir zum ExCel London zur\xfcck, um zu zeigen, woran wir gearbeitet haben! Dieses Mal sind wir in der Startup Zone am Stand FS10 im South Stand, und ich kann es kaum erwarten, P\xe4dagogen, Sch\xfcler und Mitinnovatoren zu treffen, die unsere Leidenschaft f\xfcr die Transformation der MINT-Bildung teilen."}),(0,s.jsx)("h2",{children:"Warum die Bett 2026 f\xfcr uns wichtig ist"}),(0,s.jsx)("p",{children:"Die Bett ist das globale Epizentrum der EdTech-Innovation und bringt \xfcber 30.000 P\xe4dagogen und 800 Aussteller aus mehr als 130 L\xe4ndern zusammen. F\xfcr ein kleines Team wie unseres mit Sitz in Edinburgh stellt die Bett eine au\xdfergew\xf6hnliche Gelegenheit dar, mit P\xe4dagogen in Kontakt zu treten, die aktiv nach L\xf6sungen f\xfcr die Herausforderungen suchen, denen wir uns verschrieben haben."}),(0,s.jsx)("p",{children:"Die letztj\xe4hrige Bett war transformativ f\xfcr WhimsyLabs. Wir trafen Lehrer, die nach der Pandemie mit dem Laborzugang zu k\xe4mpfen hatten, Schulleiter, die versuchten, Nachhaltigkeitsverpflichtungen mit praxisorientierter naturwissenschaftlicher Bildung in Einklang zu bringen, und Sch\xfcler, die auflebten, als sie erkannten, dass sie echte Experimente in unserer virtuellen Umgebung durchf\xfchren konnten. Diese Gespr\xe4che best\xe4tigten alles, woran wir gearbeitet haben, und inspirierten uns, unsere Plattform noch weiter voranzutreiben."}),(0,s.jsx)("img",{src:"/images/bett map.jpg",alt:"Karte zum WhimsyLabs-Stand auf der Bett-Ausstellung",className:"rounded shadow center limited-size",style:{width:"0px",height:"0px",margin:"0",padding:"0",border:"none",position:"absolute",visibility:"hidden"}}),(0,s.jsx)("div",{style:{margin:"2rem 0"},children:(0,s.jsx)(r.A,{imagePath:"/images/bett map.jpg",pathData:"M 404 96 L 404 185 L 360 185 L 360 646 L 418 646 L 419 679 L 397 681",viewBox:"0 0 938 785",speed:3e-4,numTokens:3})}),(0,s.jsx)("p",{className:"caption",children:"Folgen Sie dem animierten Pfad, um unseren Stand FS10 in der South Stand Startup Zone zu finden \u2013 wir haben Live-Demos und praktische Erfahrungen f\xfcr Sie bereit."}),(0,s.jsx)("h2",{children:"Was wir dieses Jahr pr\xe4sentieren"}),(0,s.jsx)("p",{children:"Seit der Bett 2025 haben wir unsere Plattform basierend auf dem Feedback der P\xe4dagogen und Sch\xfcler, mit denen wir zusammenarbeiten, kontinuierlich verbessert. Auf der Bett 2026 k\xf6nnen Sie aus erster Hand erleben, was WhimsyLabs von herk\xf6mmlichen virtuellen Laborsimulationen unterscheidet. Wie im letzten Jahr haben wir eine vollst\xe4ndige Sandbox-Umgebung mitgebracht, in der echte Entdeckungen stattfinden, aber dieses Mal pr\xe4sentieren wir eine ganze Reihe verschiedener Experimente aus Chemie, Biologie und Physik!"}),(0,s.jsx)("p",{children:'Unser \u201ePhysikalit\xe4t-zuerst"-Ansatz bedeutet, dass Sie beim Interagieren mit unserem virtuellen Labor dasselbe Muskelged\xe4chtnis und dieselbe Verfahrenskompetenz entwickeln, die Sie in einem physischen Labor erwerben w\xfcrden. Forschung zeigt konsistent, dass verk\xf6rpertes Lernen \u2013 bei dem physische Handlungen mit kognitiven Prozessen integriert werden \u2013 die Retention und das Verst\xe4ndnis in der naturwissenschaftlichen Bildung erheblich verbessert. An unserem Stand werden Sie sofort verstehen, was dies in der Praxis bedeutet.'}),(0,s.jsx)("p",{children:"Wir werden auch unsere plattform\xfcbergreifende Kompatibilit\xe4t demonstrieren. Egal, ob Sie VR-Headsets, Laptops oder Chromebooks verwenden, WhimsyLabs bietet ein nahtloses Erlebnis, das f\xfcr Ihre Hardware optimiert ist. Diese Flexibilit\xe4t ist entscheidend f\xfcr Schulen mit vielf\xe4ltigen Technologie-\xd6kosystemen und stellt sicher, dass alle Sch\xfcler Zugang zu hochwertigen Laborerfahrungen haben, unabh\xe4ngig von den ihnen zur Verf\xfcgung stehenden Ger\xe4ten. Probieren Sie die Desktop/Chromebooks-Version der Software aus und sehen Sie, wie sie das Lernerlebnis Ihrer Sch\xfcler transformiert, ohne Kompromisse bei Interaktivit\xe4t oder Immersion."}),(0,s.jsx)("h2",{children:"Innovationen, die wir gerne demonstrieren"}),(0,s.jsx)("p",{children:"Wir werden mehrere Funktionen pr\xe4sentieren, auf die ich besonders stolz bin, einschlie\xdflich unserer erweiterten Bewertungsf\xe4higkeiten. Eine der gr\xf6\xdften Herausforderungen f\xfcr P\xe4dagogen besteht darin, praktische Laborf\xe4higkeiten auf authentische und skalierbare Weise zu bewerten. Traditionelle Laborberichte erfassen oft nicht die tats\xe4chliche Kompetenz eines Sch\xfclers in Labortechniken."}),(0,s.jsx)("p",{children:'Zus\xe4tzlich zu diesem Problem werden wissenschaftliche Pr\xfcfungen und Kursarbeiten zunehmend durch KI-Tools beeinflusst, die mit minimalem Aufwand seitens der Sch\xfcler textbasierte Berichte erstellen k\xf6nnen. Um dies anzugehen, erm\xf6glicht unsere Plattform den Sch\xfclern, ihre eigenen einzigartigen experimentellen Daten zu verwenden, die sie durch ihre eigenen Handlungen sammeln, was personalisierte Bewertungsfragen erm\xf6glicht, die an ihre individuellen Ergebnisse gebunden sind. Dies bedeutet, dass keine zwei Sch\xfcler identische Fragen erhalten, wodurch die Plagiatsprobleme und das Problem beseitigt werden, dass Sch\xfcler ChatGPT verwenden, um ihre Laborberichte zu erstellen, die traditionelle Laborberichte plagen, w\xe4hrend eine authentischere Bewertung des Verst\xe4ndnisses bereitgestellt wird. Durch die Abkehr von statischen \u201eAntwortschl\xfcsseln", die auf Websites wie Chegg zu finden sind, zwingen wir die Sch\xfcler, sich mit den Daten auseinanderzusetzen, die sie tats\xe4chlich generiert haben, und ihre eigenen Schritte zu rechtfertigen, ihre eigenen Daten zu entrauschen und sinnvolle Schlussfolgerungen zu ziehen, was den gesamten Prozess authentischer und schwerer zu \u201ebetr\xfcgen" macht als traditionelle Multiple-Choice-Fragen. Wir haben festgestellt, dass Sch\xfcler, die \u201eschummeln", effektiv die Handlungen ausf\xfchren, die ein Sch\xfcler, der nicht geschummelt hat, tun w\xfcrde; indem sie nachschlagen, wie man das Experiment durchf\xfchrt, Rauschen reduziert und ihre eigenen Daten analysiert, lernen sie das Material sowieso!'}),(0,s.jsx)("p",{children:"Unser automatisiertes Bewertungssystem hat sich ebenfalls erheblich weiterentwickelt. Lehrer sagen uns durchweg, dass das Korrigieren von Laborberichten eine ihrer zeitaufw\xe4ndigsten Aufgaben ist, wobei einige bis zu 4-5 Stunden pro Woche allein f\xfcr diese Aufgabe aufwenden. Unser System bewertet Labortechnik und experimentellen Ansatz in Echtzeit, bietet den Sch\xfclern sofortiges Feedback und spart P\xe4dagogen durchschnittlich 3,5 Stunden pro Woche. Das ist Zeit, die Lehrer in den Unterricht statt in Verwaltungsaufgaben reinvestieren k\xf6nnen."}),(0,s.jsxs)("p",{children:['Da unsere Simulation auf einer physikbasierten \u201eSandbox" und nicht auf einem starren Skript basiert, kann unsere KI den ',(0,s.jsx)("i",{children:"Prozess"}),' und nicht das Endergebnis bewerten. Dies bedeutet, dass wir nuancierte Aspekte der Technik bewerten k\xf6nnen; hat der Sch\xfcler die Schleife korrekt sterilisiert? Haben sie zu schnell titriert? Die Handlungen, die Probleml\xf6sungsf\xe4higkeiten und der einzigartige Ansatz des Sch\xfclers werden gemessen. Und wie Ihnen jeder Wissenschaftler sagen wird, sind Daten verrauscht. Unser System ist so konzipiert, dass es Hintergrundrauschen und Zuf\xe4lligkeit aufweist, wie z. B. wechselnde Luftfeuchtigkeit, Temperatur, Kontamination, Lichtverh\xe4ltnisse und andere Faktoren, wodurch es realistischer und schwerer zu \u201emanipulieren" ist als traditionelle Multiple-Choice-Fragen.']}),(0,s.jsx)("p",{children:"Das vielleicht Aufregendste ist unser individueller Experimentbauer, der n\xe4chstes Jahr eingef\xfchrt wird und jetzt KI-Unterst\xfctzung f\xfcr die Lehrplanausrichtung beinhaltet. P\xe4dagogen k\xf6nnen ma\xdfgeschneiderte Laborszenarien entwerfen, die ihren spezifischen Lehrplananforderungen entsprechen, egal ob sie GCSE-Chemie, IB-Biologie oder Advanced Placement Physics unterrichten. Die Flexibilit\xe4t hier ist wirklich beispiellos; schauen Sie unbedingt vorbei und sehen Sie sich unsere Videodemonstration dieser neuen Funktion an!"}),(0,s.jsx)("h2",{children:"Warum die Startup Zone f\xfcr uns gem\xfctlich ist"}),(0,s.jsx)("p",{children:"Wir haben uns speziell f\xfcr die Ausstellung in der Startup Zone entschieden, weil sie repr\xe4sentiert, was wir sind: ein innovatives, agiles Team, das sich der L\xf6sung realer Probleme auf kreative Weise verschrieben hat. Hier kommen P\xe4dagogen hin, um die Zukunft der Bildungstechnologie zu entdecken, nicht nur inkrementelle Verbesserungen bestehender L\xf6sungen. Es bietet uns auch Platz, um unsere VR-Ausr\xfcstung aufzubauen und interaktivere Demos zu haben, als wir es in einem gr\xf6\xdferen, gesch\xe4ftigeren Stand k\xf6nnten."}),(0,s.jsx)("p",{children:"In der Startup Zone zu sein bedeutet auch, dass wir bedeutungsvollere, tiefgreifendere Gespr\xe4che f\xfchren k\xf6nnen. Wir versuchen nicht, Tausende von schnellen Verk\xe4ufen zu t\xe4tigen, wir m\xf6chten Ihre spezifischen Herausforderungen verstehen, demonstrieren, wie WhimsyLabs diese angeht, und herausfinden, ob wir die richtige Wahl f\xfcr Ihre Einrichtung sind. Die intimere Atmosph\xe4re der Startup Zone erleichtert genau diese Art von substanziellen Diskussionen. Sie erm\xf6glicht es uns, st\xe4rkere Verbindungen zu P\xe4dagogen aufzubauen, die ebenso leidenschaftlich daran interessiert sind, die MINT-Bildung zu verbessern wie wir, damit unsere ersten Nutzer, wenn wir unsere Plattform \xf6ffentlich starten, diejenigen sind, mit denen wir Beziehungen aufgebaut haben und deren Bed\xfcrfnisse wir tiefgehend verstehen."}),(0,s.jsx)("h2",{children:"Barrierefreiheit und Inklusivit\xe4t im Kern"}),(0,s.jsx)("p",{children:"Ein Aspekt von WhimsyLabs, \xfcber den ich auf der Bett 2026 leidenschaftlich sprechen m\xf6chte, ist unser Engagement f\xfcr Barrierefreiheit. Wir haben SEND-Kompatibilit\xe4t und multisensorische Lernhilfen von Anfang an direkt in unsere Plattform integriert, nicht als nachtr\xe4gliche Gedanken. Forschung zeigt, dass bis zu 15% der Sch\xfcler in der Regelschulbildung besondere p\xe4dagogische Bed\xfcrfnisse haben, und traditionelle Labore stellen f\xfcr diese Lernenden oft erhebliche Barrieren dar."}),(0,s.jsx)("p",{children:"Unsere virtuelle Umgebung erm\xf6glicht anpassbare Geschwindigkeit, anpassbare sensorische Eingaben und flexible Interaktionsmodi, die sich an individuelle Sch\xfclerbed\xfcrfnisse anpassen. Sch\xfcler, die m\xf6glicherweise mit der sensorischen \xdcberw\xe4ltigung eines physischen Labors zu k\xe4mpfen haben \u2013 wie chemische Ger\xfcche, L\xe4rm, sozialer Druck oder potenzielle Gefahren \u2013 k\xf6nnen in ihrem eigenen Tempo in einer Umgebung lernen, die sie kontrollieren. Es geht nicht darum, Standards zu senken; es geht darum, unn\xf6tige Lernbarrieren zu beseitigen und gleichzeitig wissenschaftliche Strenge aufrechtzuerhalten."}),(0,s.jsx)("h2",{children:"Nachhaltigkeit: Mehr als nur ein Schlagwort"}),(0,s.jsx)("p",{children:"Wir haben ausf\xfchrlich \xfcber die Umweltvorteile virtueller Labore geschrieben, und dies wird ein Hauptfokus an unserem Bett 2026-Stand sein. Traditionelle naturwissenschaftliche Labore verbrauchen enorme Ressourcen; bis zu f\xfcnfmal mehr Energie und Wasser als typische B\xfcror\xe4ume \u2013 und erzeugen erheblichen Plastikm\xfcll durch Einwegverbrauchsmaterialien."}),(0,s.jsx)("p",{children:"Da sich Schulen weltweit zu Kohlenstoffneutralit\xe4tszielen verpflichten, k\xe4mpfen viele damit, wie sie qualitativ hochwertige MINT-Bildung aufrechterhalten und gleichzeitig ihre Umweltauswirkungen reduzieren k\xf6nnen. WhimsyLabs bietet eine konkrete L\xf6sung: unbegrenzte Experimente mit null physischem Abfall, 98% Reduzierung des Energieverbrauchs im Vergleich zu traditionellen Laboren und keine laufenden Kosten f\xfcr Verbrauchsmaterialien oder Entsorgung gef\xe4hrlicher Abf\xe4lle. Auf der Bett haben wir detaillierte Auswirkungsberechnungen verf\xfcgbar, damit Sie genau sehen k\xf6nnen, wie WhimsyLabs zu den Nachhaltigkeitszielen Ihrer Einrichtung beitragen k\xf6nnte."}),(0,s.jsx)("h2",{children:"Was Sie am Stand FS10 erwarten k\xf6nnen"}),(0,s.jsx)("p",{children:"Wenn Sie unseren Stand besuchen, finden Sie keinen polierten Verkaufsvortrag oder eine sorgf\xe4ltig einstudierte Demonstration. Was Sie finden werden, sind ich und mein Team, die wirklich begeistert sind, Ihnen zu zeigen, was wir gebaut haben, und ehrlich zu besprechen, ob es zu Ihren Bed\xfcrfnissen passt. Wir haben beide Ger\xe4tetypen aufgebaut; VR-Headsets und einen Laptop, damit Sie unsere Plattform \xfcber verschiedene Modalit\xe4ten erleben und sehen k\xf6nnen, wie sie auf der Hardware funktioniert, die Ihre Schule verwendet. Da wir den Zugriff auf VR oder Desktop nicht einschr\xe4nken, k\xf6nnen Sie die Plattform auf die Weise erleben, die Ihren Bed\xfcrfnissen am besten entspricht, genau so, wie Ihre Sch\xfcler es tun werden."}),(0,s.jsx)("p",{children:"Sie k\xf6nnen tats\xe4chliche Experimente durchf\xfchren, nicht nur zusehen, wie jemand anderes sie durchf\xfchrt. Chemikalien mischen und realistische Reaktionen beobachten. Physikexperimente aufbauen und Variablen in Echtzeit manipulieren. Virtuelle Pr\xe4parate mit der richtigen Technik sezieren. Das Ziel ist, dass Sie viszerall verstehen, was unseren Ansatz anders macht; warum unsere Sch\xfcler berichten, dass sich WhimsyLabs wie ein echtes Labor anf\xfchlt, auf eine Weise, wie es andere virtuelle Plattformen nicht tun, und warum wir diejenigen sind, die die Sch\xfclerwahl-Auszeichnungen f\xfcr eine unterhaltsame und lehrreiche Plattform gewinnen."}),(0,s.jsx)("p",{children:"Wir werden auch Fallstudien von Schulen haben, die derzeit WhimsyLabs verwenden, einschlie\xdflich Daten zu Lernergebnissen, Zeitersparnis f\xfcr Lehrer und Sch\xfclerengagement-Metriken. Dies sind keine handverlesenen Erfolgsgeschichten \u2013 es sind ehrliche Bewertungen von P\xe4dagogen, die unsere Plattform in ihren Unterricht integriert haben und sowohl \xfcber ihre St\xe4rken als auch \xfcber Bereiche sprechen k\xf6nnen, in denen wir uns noch verbessern."}),(0,s.jsx)("h2",{children:"Warum Sie uns besuchen sollten"}),(0,s.jsx)("p",{children:"Wenn Sie mit dem Laborzugang zu k\xe4mpfen haben, sei es aufgrund von Budgetbeschr\xe4nkungen, Einrichtungseinschr\xe4nkungen oder Sicherheitsbedenken, sollten Sie uns besuchen. Wenn Sie nach M\xf6glichkeiten suchen, die MINT-Bildung inklusiver und f\xfcr verschiedene Lernende zug\xe4nglicher zu machen, sollten Sie uns besuchen. Wenn Sie versuchen, Lehr-/Verwaltungsverpflichtungen mit praxisorientiertem naturwissenschaftlichem Unterricht in Einklang zu bringen, sollten Sie uns besuchen."}),(0,s.jsx)("p",{children:"Aber selbst wenn keine dieser spezifischen Herausforderungen auf Sie zutrifft, w\xfcrde ich Sie gerne treffen. Vielleicht sind Sie einfach neugierig, wohin EdTech f\xfchrt, oder Sie m\xf6chten verstehen, wie virtuelle Realit\xe4t in der Bildung jenseits von Spielen und Unterhaltung angewendet wird. Vielleicht sind Sie ein Sch\xfcler oder P\xe4dagoge mit Ideen dar\xfcber, was virtuelle Labore tun sollten, was sie derzeit nicht tun. Jedes Gespr\xe4ch ist wertvoll f\xfcr uns; sie helfen uns zu verstehen, worauf wir unsere Entwicklungsbem\xfchungen konzentrieren sollten, und stellen sicher, dass wir echte Probleme l\xf6sen, nicht eingebildete."}),(0,s.jsx)("h2",{children:"Jenseits der Ausstellungsfl\xe4che"}),(0,s.jsx)("p",{children:"Bei der Bett geht es um mehr als nur das, was in den Ausstellungshallen passiert. Es geht um die Gespr\xe4che w\xe4hrend der Kaffeepausen, die Verbindungen, die beim Anstehen f\xfcr Demonstrationen entstehen, die Ideen, die entstehen, wenn P\xe4dagogen aus verschiedenen Kontexten ihre Erfahrungen teilen. Ich hoffe, viele dieser informellen Diskussionen w\xe4hrend der Veranstaltung zu f\xfchren."}),(0,s.jsx)("p",{children:"Wenn Sie eine bestimmte Zeit vereinbaren m\xf6chten, um uns zu treffen, oder wenn Sie bestimmte Fragen haben, auf die wir uns vorbereiten sollen, melden Sie sich bitte im Voraus. Wir nehmen uns gerne Zeit f\xfcr tiefergehende Diskussionen \xfcber Implementierung, Lehrplanintegration, technische Anforderungen oder alles andere, das f\xfcr Ihren Entscheidungsprozess wichtig ist. Sie k\xf6nnen uns unter hello@whimsylabs.ai kontaktieren."}),(0,s.jsx)("p",{children:"Wir hoffen, Sie am Stand FS10 vom 21. bis 23. Januar 2026 zu sehen. Bringen Sie Ihre Neugier, Ihre Fragen und Ihre Leidenschaft f\xfcr MINT-Bildung mit. Wir bringen unsere mit, zusammen mit einigen wirklich aufregenden Technologien, die Sie lieben werden."})]})}}]);
